// =============================================================================
// main.cpp — startup and the control task. Owner: lead.
//
// Two tasks:
//   * control task (core 1, 100x/s): sensors, adhesion, wheels, failsafe.  <- this file
//   * comms task   (core 0): WiFi, web server, WebSocket.                  <- src/comms/
// They share data only through shared_state.h.
//
// Module owners: do NOT edit this file. Fill in your own module's .cpp file.
// =============================================================================
#include <Arduino.h>

#include "adhesion.h"
#include "comms.h"
#include "config.h"
#include "locomotion.h"
#include "sensors.h"
#include "shared_state.h"
#include "state_machine.h"
#include "version.h"

static void controlTask(void*) {
  RobotState previous = RobotState::ESTOP;
  TickType_t lastWake = xTaskGetTickCount();

  for (;;) {
    // 1. read
    sensorsUpdate();
    adhesionUpdate();
    const Commands commands = sharedGetCommands();
    const uint32_t now = millis();  // read AFTER the commands (see ageMs in state_machine.cpp)

    // 2. decide
    const RobotState state = robotState(commands, now);
    if (state != previous) {
      Serial.printf("state %s -> %s\n", stateName(previous), stateName(state));
      previous = state;
    }
    const Outputs out = computeOutputs(commands, state, now);

    // 3. act (every loop, so a missed command can never leave a motor running)
    adhesionSetPower(out.adhesionPct);
    if (state == RobotState::RUNNING) {
      setMotorSpeed(out.leftPct, out.rightPct);
    } else {
      stopMotors();
    }

    // 4. report (comms sends it to the web UI)
    const SensorData sensors = sensorsGet();
    TelemetryData t;
    t.state = stateName(state);
    t.estop = commands.estopLatched;
    t.linkOk = state != RobotState::LINK_LOST;
    t.batteryV = sensors.batteryV;
    t.batteryValid = sensors.batteryValid;
    t.adhesionPct = adhesionGetPower();
    t.adhesionOk = adhesionIsOk();
    t.motorLeftPct = out.leftPct;
    t.motorRightPct = out.rightPct;
    t.pitchDeg = sensors.pitchDeg;
    t.rollDeg = sensors.rollDeg;
    t.tiltValid = sensors.tiltValid;
    t.uptimeMs = now;
    sharedPublishTelemetry(t);

    // Wait until the next period. Unlike delay(), this keeps a steady rate.
    vTaskDelayUntil(&lastWake, pdMS_TO_TICKS(CONTROL_LOOP_PERIOD_MS));
  }
}

void setup() {
  Serial.begin(SERIAL_BAUD);
  Serial.printf("wallclimbingbot firmware %s, protocol %d\n", FIRMWARE_VERSION, PROTOCOL_VERSION);

  sharedStateInit();
  sensorsInit();
  adhesionInit();
  locomotionInit();

  xTaskCreatePinnedToCore(controlTask, "control", CONTROL_TASK_STACK, nullptr,
                          CONTROL_TASK_PRIORITY, nullptr, CONTROL_TASK_CORE);
  commsStart();
  Serial.println("started in ESTOP: press Reset in the web UI to arm");
}

void loop() {
  // Not used: all work happens in the two tasks above.
  vTaskDelete(nullptr);
}
